<?php
declare(strict_types=1);

namespace ProjectO\Storage;

use Throwable;

/**
 * Best-effort filesystem cache for remotely stored image objects.
 *
 * Object keys generated by this platform embed 16 random bytes, so a key never
 * changes content once it has been written. That makes a long TTL safe and lets
 * the application serve private images without paying a multi-second remote
 * round trip on every page view.
 *
 * Every failure mode degrades to a plain remote read: an unwritable directory,
 * a partial file, a corrupt entry or an oversized cache must never break image
 * delivery or expose a partial payload to the browser.
 */
final class LocalImageCache
{
    /** Default cache lifetime in seconds (7 days). */
    public const DEFAULT_TTL = 604800;

    /** Default ceiling for the whole cache directory, in bytes (512 MiB). */
    public const DEFAULT_MAX_BYTES = 536870912;

    private string $directory;
    private int $ttl;
    private int $maxBytes;
    private ?bool $available = null;

    public function __construct(?string $directory = null, ?int $ttl = null, ?int $maxBytes = null)
    {
        $this->directory = $directory ?? self::defaultDirectory();
        $this->ttl = $ttl !== null && $ttl >= 0 ? $ttl : self::configuredTtl();
        $this->maxBytes = $maxBytes !== null && $maxBytes > 0 ? $maxBytes : self::configuredMaxBytes();
    }

    /**
     * Whether the cache directory can be used. A disabled cache (TTL of 0 or an
     * unwritable directory) means callers go straight to remote storage.
     */
    public function isEnabled(): bool
    {
        if ($this->available !== null) {
            return $this->available;
        }

        if ($this->ttl <= 0 || $this->directory === '') {
            $this->available = false;

            return false;
        }

        try {
            if (!is_dir($this->directory) && !mkdir($this->directory, 0o750, true) && !is_dir($this->directory)) {
                $this->available = false;

                return false;
            }
            $this->available = is_writable($this->directory) && is_readable($this->directory);
        } catch (Throwable $exception) {
            error_log('Image cache directory is unusable: ' . $exception->getMessage());
            $this->available = false;
        }

        return $this->available;
    }

    /**
     * Returns cached bytes for the key, or null on a miss, an expired entry or
     * any read problem. Callers must treat null as "fetch remotely".
     */
    public function get(string $objectKey): ?string
    {
        if (!$this->isEnabled()) {
            return null;
        }

        $path = $this->path($objectKey);
        if (!is_file($path)) {
            return null;
        }

        // A size of 0 means a previous write never completed; drop it.
        $size = @filesize($path);
        if ($size === false || $size <= 0) {
            @unlink($path);

            return null;
        }

        if ((time() - (int) (@filemtime($path) ?: 0)) > $this->ttl) {
            @unlink($path);

            return null;
        }

        $contents = @file_get_contents($path);
        if (!is_string($contents) || $contents === '') {
            return null;
        }

        return $contents;
    }

    /**
     * Stores bytes under the key. Returns false when the entry was not
     * persisted; the caller already holds the bytes and serves them normally.
     */
    public function put(string $objectKey, string $contents): bool
    {
        if (!$this->isEnabled() || $contents === '') {
            return false;
        }

        // Keep oversized objects out of the cache instead of evicting useful
        // entries on every single request.
        if (strlen($contents) > intdiv($this->maxBytes, 4)) {
            return false;
        }

        $path = $this->path($objectKey);
        $shardDirectory = dirname($path);
        try {
            if (!is_dir($shardDirectory) && !mkdir($shardDirectory, 0o750, true) && !is_dir($shardDirectory)) {
                return false;
            }

            // Write to a unique temporary file first so a concurrent reader can
            // never observe a partially written image.
            $temporary = $path . '.' . bin2hex(random_bytes(6)) . '.tmp';
            if (file_put_contents($temporary, $contents, LOCK_EX) === false) {
                @unlink($temporary);

                return false;
            }
            if (!rename($temporary, $path)) {
                @unlink($temporary);

                return false;
            }
            @chmod($path, 0o640);
        } catch (Throwable $exception) {
            error_log('Unable to cache an image locally: ' . $exception->getMessage());

            return false;
        }

        $this->pruneIfOversized();

        return true;
    }

    /**
     * Removes a single key, used when the caller discovers a cached object no
     * longer exists remotely.
     */
    public function forget(string $objectKey): void
    {
        if ($this->directory === '') {
            return;
        }

        @unlink($this->path($objectKey));
    }

    /** Cache directory reported on the settings screen; never contains secrets. */
    public function directory(): string
    {
        return $this->directory;
    }

    public function ttl(): int
    {
        return $this->ttl;
    }

    /**
     * Describes cache occupancy for the settings screen so a silently disabled
     * or oversized cache stays diagnosable.
     *
     * @return array{directory: string, enabled: bool, writable: bool, ttl: int, entries: int, bytes: int}
     */
    public function status(): array
    {
        $enabled = $this->isEnabled();
        $statistics = $this->statistics();

        return [
            'directory' => $this->directory,
            'enabled' => $enabled,
            'writable' => $enabled,
            'ttl' => $this->ttl,
            'entries' => $statistics['entries'],
            'bytes' => $statistics['bytes'],
        ];
    }

    /**
     * Removes the oldest entries once the cache grows past the configured
     * ceiling. Bounded work per request: one scan of the shard directories.
     */
    private function pruneIfOversized(): void
    {
        try {
            $statistics = $this->statistics();
            $total = $statistics['bytes'];
            if ($total <= $this->maxBytes || $statistics['files'] === []) {
                return;
            }

            // Oldest first, deleting until we are back under the ceiling.
            $files = $statistics['files'];
            uasort($files, static fn (array $a, array $b): int => $a[0] <=> $b[0]);
            foreach ($files as $path => $meta) {
                if ($total <= $this->maxBytes) {
                    break;
                }
                if (@unlink((string) $path)) {
                    $total -= (int) $meta[1];
                }
            }
        } catch (Throwable $exception) {
            error_log('Unable to prune the image cache: ' . $exception->getMessage());
        }
    }

    /**
     * Scans the cache once and reports totals plus per-file metadata.
     *
     * @return array{entries: int, bytes: int, files: array<string, array{0: int, 1: int}>}
     */
    private function statistics(): array
    {
        $files = [];
        $total = 0;
        $entries = @scandir($this->directory);
        if (!is_array($entries)) {
            return ['entries' => 0, 'bytes' => 0, 'files' => []];
        }

        foreach ($entries as $entry) {
            if ($entry === '.' || $entry === '..') {
                continue;
            }
            $path = $this->directory . DIRECTORY_SEPARATOR . $entry;
            if (is_file($path)) {
                $size = (int) (@filesize($path) ?: 0);
                $total += $size;
                $files[$path] = [(int) (@filemtime($path) ?: 0), $size];
                continue;
            }
            if (!is_dir($path)) {
                continue;
            }
            foreach ((array) @scandir($path) as $nested) {
                if ($nested === '.' || $nested === '..') {
                    continue;
                }
                $nestedPath = $path . DIRECTORY_SEPARATOR . $nested;
                if (!is_file($nestedPath)) {
                    continue;
                }
                $size = (int) (@filesize($nestedPath) ?: 0);
                $total += $size;
                $files[$nestedPath] = [(int) (@filemtime($nestedPath) ?: 0), $size];
            }
        }

        return ['entries' => count($files), 'bytes' => $total, 'files' => $files];
    }

    /**
     * Maps an object key to a sharded path. The key is hashed so bucket keys
     * containing slashes or traversal segments cannot escape the cache
     * directory, and the first two hex characters shard entries across
     * sub-directories.
     */
    private function path(string $objectKey): string
    {
        $hash = hash('sha256', $objectKey);

        return $this->directory . DIRECTORY_SEPARATOR . substr($hash, 0, 2) . DIRECTORY_SEPARATOR . $hash;
    }

    private static function defaultDirectory(): string
    {
        $configured = trim((string) getenv('APP_IMAGE_CACHE_DIR'));
        if ($configured !== '') {
            return $configured;
        }

        return dirname(__DIR__, 2) . DIRECTORY_SEPARATOR . 'storage' . DIRECTORY_SEPARATOR . 'image-cache';
    }

    private static function configuredTtl(): int
    {
        $configured = filter_var(getenv('APP_IMAGE_CACHE_TTL'), FILTER_VALIDATE_INT);

        return is_int($configured) && $configured >= 0 ? $configured : self::DEFAULT_TTL;
    }

    private static function configuredMaxBytes(): int
    {
        $megabytes = filter_var(getenv('APP_IMAGE_CACHE_MAX_MB'), FILTER_VALIDATE_INT);
        if (is_int($megabytes) && $megabytes > 0) {
            return $megabytes * 1048576;
        }

        return self::DEFAULT_MAX_BYTES;
    }
}
